export type SceneName = keyof typeof scenes;

export function HomeIllustration({
  name,
  label,
  className = "",
}: {
  name: SceneName;
  /** Lo que ensena la escena, para el lector de pantalla. */
  label: string;
  className?: string;
}) {
  const scene = scenes[name];
  // El clipPath de "work" lleva id: cada variante necesita el suyo, porque la
  // que esta oculta con display:none no puede prestarselo a la otra.
  const desktop = scene.markup.replaceAll("ill-clip", `ill-clip-${name}-d`);
  const mobile = scene.markup.replaceAll("ill-clip", `ill-clip-${name}-m`);
  return (
    <div className={className}>
      <svg
        viewBox={scene.viewBox}
        role="img"
        aria-label={label}
        className={`block h-auto w-full ${scene.mobileViewBox ? "max-md:hidden" : ""}`}
        dangerouslySetInnerHTML={{ __html: desktop }}
      />
      {scene.mobileViewBox ? (
        <svg
          viewBox={scene.mobileViewBox}
          role="img"
          aria-label={label}
          className="block h-auto w-full md:hidden"
          dangerouslySetInnerHTML={{ __html: mobile }}
        />
      ) : null}
    </div>
  );
}
